  def assessment_context_Id : Art.PortId
  def qualified_evidence_Id : Art.PortId
  def decision_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var decision_assessment: Battery_Status_Assessment_Service.TaggedAssessment = $

  def put_decision_assessment(value : Battery_Status_Assessment_Service.TaggedAssessment) : Unit = {
    Contract(
      Modifies(decision_assessment),
      Ensures(
        decision_assessment == value
      )
    )
    Spec {
      decision_assessment = value
    }

    Art.putValue(decision_assessment_Id, Battery_Status_Assessment_Service.TaggedAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

